def solve(intervals):
    expanded = [(s - 10, e + 10) for s, e in intervals]
    expanded.sort(key=lambda x: x[0])
    merged = []
    for interval in expanded:
        if not merged:
            merged.append(interval)
        else:
            last = merged[-1]
            # Check if intervals strictly overlap (overlap length > 0)
            if interval[0] < last[1]:
                merged[-1] = (last[0], max(last[1], interval[1]))
            else:
                merged.append(interval)
    return merged
```

