                if interval[0] < last[1] and interval[1] > last[0]:
                    new_merged[-1] = (min(last[0], interval[0]), max(last[1], interval[1]))
                    changed = True
                else:
                    new_merged.append(interval)
        merged = new_merged
    return merged
